            '<li><a href="https://commons.wikimedia.org/wiki/File:Safe_boda.jpg">Safe boda</a> by Mutegekicliff, <a href="https://creativecommons.org/licenses/by-sa/4.0">CC BY-SA 4.0</a></li>',
            '<li><a href="https://commons.wikimedia.org/wiki/File:Boda_boda_(Motorcycle_centre).jpg">Boda boda (motorcycle centre)</a> by Elisha Muwanguzi, <a href="https://creativecommons.org/licenses/by-sa/4.0">CC BY-SA 4.0</a></li>',
            '<li><a href="https://commons.wikimedia.org/wiki/File:Boda_boda_with_passenger.jpg">Boda boda with passenger</a> by Mutegekicliff, <a href="https://creativecommons.org/licenses/by-sa/4.0">CC BY-SA 4.0</a></li>',
            '<li><a href="https://commons.wikimedia.org/wiki/File:Boda_boda_team.jpg">Boda boda team</a> by Mutegekicliff, <a href="https://creativecommons.org/licenses/by-sa/4.0">CC BY-SA 4.0</a></li>',
            '<li><a href="https://commons.wikimedia.org/wiki/File:A_morning_in_Lira_City_Lira_District.jpg">A morning in Lira City</a> by Aqoragye, <a href="https://creativecommons.org/licenses/by-sa/4.0">CC BY-SA 4.0</a></li>',
            '<li><a href="https://commons.wikimedia.org/wiki/File:OYAM_ROAD-_LIRA_CITY.jpg">Oyam Road, Lira City</a> by Jastine Okwir, <a href="https://creativecommons.org/licenses/by-sa/4.0">CC BY-SA 4.0</a></li>',
            '<li><a href="https://commons.wikimedia.org/wiki/File:Sunset_in_lira_uganda.jpg">Sunset in Lira, Uganda</a>, released into the public domain (<a href="https://creativecommons.org/publicdomain/zero/1.0/">CC0</a>)</li>',
            '</ul>',
            '<p>A photo you uploaded yourself in Super Admin, Pages and content, replaces these on your own site.</p>'
