    'items' => [
        // home_slide: group, icon, title, body, sort, image, button label, button link
        ['home_slide', 'fa-users', 'Every rider registered at the stage they work from', 'A rider with a name, a photo, a number plate and a stage on record can be traced, trusted by passengers and reached by the council. Chairpersons register riders where they already work.', 1, '/assets/images/home/stage-riders.webp', 'Sign in to your portal', '/login.php'],
        ['home_slide', 'fa-qrcode', 'Check a permit in seconds, at the roadside', 'Scan the QR code on the rider\'s ID card with any phone camera. The page shows straight away whether the permit is valid, expired or pending, with no paperwork and no phone calls.', 2, '/assets/images/home/kampala-junction.webp', 'Check a permit now', '/verify.php'],
        ['home_slide', 'fa-money-bill-wave', 'Permit fees that reach the council, with a receipt', 'Cash paid at the stage and mobile money paid from the rider\'s phone both get a receipt number and land in the council\'s revenue report, so no payment goes unrecorded.', 3, '/assets/images/home/safe-boda.webp', 'See how BodaERP works', '/#how-it-works'],
        ['home_slide', 'fa-location-dot', 'Riders who can prove their permit keep working', 'A valid permit on the ID card or the rider\'s phone settles a checkpoint stop at once. Riders see their renewal date, pay on time and keep every receipt.', 4, '/assets/images/home/lira-morning.webp', 'Answers for riders', '/faq.php'],
        ['home_why', 'fa-user-shield', 'Safer trips for passengers', 'A passenger can check a rider before the trip. If something goes wrong, the rider can be traced through their stage and their record.', 1],
        ['home_why', 'fa-coins', 'Fees that are accounted for', 'Cash collected at a stage is receipted and handed over on record, so the council knows what was paid, by whom and what is still owed.', 2],
        ['home_why', 'fa-scale-balanced', 'Fair checks for riders', 'A rider with a valid permit proves it in seconds. A check rests on the record, not on an argument at the roadside.', 3],
        ['home_why', 'fa-chart-line', 'Plans based on real numbers', 'Councils decide where to enforce, which stages need help and what to charge from live registration and payment figures.', 4],
        ['home_step', 'fa-city', 'The council sets the rules', 'The city council enters its stages, the yearly permit fee and the grace period. Every chairperson and officer then works from the same rules.', 1],
        ['home_step', 'fa-user-plus', 'Chairpersons register riders at the stage', 'The chairperson knows every rider at the stage, so they record each rider\'s NIN, photo and plate, and collect the fee in cash or by mobile money.', 2],
        ['home_step', 'fa-id-card', 'Each rider gets an ID card', 'The card carries the rider\'s photo, stage and a QR code. Riders with an email address or phone number also get a portal for receipts and renewals.', 3],
        ['home_step', 'fa-qrcode', 'Anyone can check a permit', 'Officers and passengers scan the QR code or type the permit number, and see at once whether the permit is valid, expired or pending.', 4],
        ['home_role', 'fa-building-columns', 'City councils', 'They set the permit fee and answer for road safety in the city. They see every stage, rider and shilling collected, follow up defaulters and plan enforcement from real figures.', 1],
        ['home_role', 'fa-users-gear', 'Stage chairpersons', 'They already know every rider at their stage by name, which makes them the right people to register riders, collect fees and hand out ID cards.', 2],
        ['home_role', 'fa-motorcycle', 'Riders', 'Their income depends on staying on the road. A permit they can show on a card or a phone, with receipts to prove payment, keeps them working.', 3],
        ['home_role', 'fa-landmark', 'Government', 'National agencies need the full picture without handling local records. They get a read-only view of registration, compliance and revenue across cities.', 4],
        ['home_feature', 'fa-user-plus', 'Register riders once, at the stage', 'Name, NIN, photo, plate and next of kin, recorded by the chairperson. A NIN or plate that is already registered is caught before it is saved twice.', 1],
        ['home_feature', 'fa-id-card', 'ID cards that prove themselves', 'Each card shows the rider\'s photo, stage and permit number. Its QR code opens the live permit status, so an expired or copied card is spotted at once.', 2],
        ['home_feature', 'fa-money-bill-wave', 'Cash or mobile money, always receipted', 'Chairpersons record cash at the stage and hand it over to the council on record. Riders can renew from their phone. Every payment has a receipt number.', 3],
        ['home_feature', 'fa-qrcode', 'Roadside checks on any phone', 'Officers scan a card with the phone camera and can note what they did. The council sees every check, where it happened and the outcome.', 4],
        ['home_feature', 'fa-bell', 'Reminders before a permit lapses', 'Riders get a text message and a portal reminder before their permit expires. Chairpersons see who is due this month.', 5],
        ['home_feature', 'fa-chart-pie', 'Reports councils can act on', 'Collections by stage and month, the agreed revenue split, defaulters and enforcement, ready to print or export.', 6],

        ['faq', null, 'How does a rider get a BodaERP account?', 'The chairperson of your stage registers you. When they add your email address, you receive a link to set your own password. There is no public sign-up, so every rider is checked by their stage first.', 1],
        ['faq', null, 'How much is the annual permit fee?', 'Each city council sets its own fee. Your portal shows the amount for your city, and the receipt shows exactly what you paid.', 2],
        ['faq', null, 'How do I pay?', 'Pay your stage chairperson in cash and they record it straight away, or sign in to your portal and pay by mobile money. Your permit is extended by one year when the payment is confirmed.', 3],
        ['faq', null, 'How can an officer check that my permit is valid?', 'They scan the QR code on your ID card. It opens a page showing your photo, stage and whether your permit is valid right now. Anyone can also type a permit number on the Verify a rider page.', 4],
        ['faq', null, 'I forgot my password. What do I do?', 'Use "Forgot password" on the sign-in page. A reset link is emailed to you and works for 30 minutes. If your account has no email address, ask your stage chairperson or city council to reset it.', 5],
        ['faq', null, 'My details are wrong. How do I fix them?', 'Ask your stage chairperson to correct them, or send a correction request from My account → Privacy and your data in your portal. Changes are recorded in the audit log.', 6],
        ['faq', null, 'Can I get a copy of the data held about me?', 'Yes. Riders can download their profile and payment history from My account → Privacy and your data, and each receipt from Payment history. You can also request a copy through the contact page.', 7],
        ['faq', null, 'Our city council wants to use BodaERP. How do we start?', 'Send a message from the contact page with your city, the number of stages and the current permit fee. The council account, stages and revenue split are set up for you, and your chairpersons are shown how to register riders.', 8],
    ],

